Q10: The Fair Tax Cap Optimizer
Description: Find smallest integer Cap C such that total tax collected \ge G.






Sample Input



3 25
10 20 30








Sample Output



9








Solution





#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

long long calculateTax(int incomes[], int n, int cap) {
    long long total = 0;
    for (int i = 0; i &lt; n; i++) {
        total += (incomes[i] &lt; cap) ? incomes[i] : cap;
    }
    return total;
}

int main() {
    int n;
    long long g;
    if (scanf("%d %lld", &n, &g) != 2) return 1;
    int *incomes = (int *)malloc(n * sizeof(int));
    int maxInc = 0;
    long long totalPossible = 0;
    for (int i = 0; i &lt; n; i++) {
        scanf("%d", &incomes[i]);
        if (incomes[i] &gt; maxInc) maxInc = incomes[i];
        totalPossible += incomes[i];
    }

    if (totalPossible &lt; g) {
        printf("-1\n");
        free(incomes);
        return 0;
    }

    int low = 0, high = maxInc, ans = maxInc;
    while (low &lt;= high) {
        int mid = low + (high - low) / 2;
        if (calculateTax(incomes, n, mid) &gt;= g) {
            ans = mid;
            high = mid - 1;
        } else low = mid + 1;
    }
    printf("%d\n", ans);
    free(incomes);
    return 0;
}

Q1: The Palindrome Check
Description: Check if a Singly Linked List is a Palindrome. Challenge: Solve in-place (using O(1) extra space).






Sample Input



5
1 2 3 2 1








Sample Output



True








Solution





#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;

struct Node {
    int data;
    struct Node* next;
};

struct Node* createList(int n) {
    struct Node *head = NULL, *tail = NULL;
    for (int i = 0; i &lt; n; i++) {
        struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
        scanf("%d", &newNode-&gt;data);
        newNode-&gt;next = NULL;
        if (!head) head = tail = newNode;
        else { tail-&gt;next = newNode; tail = newNode; }
    }
    return head;
}

void freeList(struct Node* head) {
    while (head) {
        struct Node* temp = head;
        head = head-&gt;next;
        free(temp);
    }
}

struct Node* reverse(struct Node* head) {
    struct Node *prev = NULL, *curr = head, *next = NULL;
    while (curr) {
        next = curr-&gt;next;
        curr-&gt;next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

bool isPalindrome(struct Node* head) {
    if (!head || !head-&gt;next) return true;
    struct Node *slow = head, *fast = head;
    while (fast-&gt;next && fast-&gt;next-&gt;next) {
        slow = slow-&gt;next;
        fast = fast-&gt;next-&gt;next;
    }
    slow-&gt;next = reverse(slow-&gt;next);
    struct Node *p1 = head, *p2 = slow-&gt;next;
    while (p2) {
        if (p1-&gt;data != p2-&gt;data) return false;
        p1 = p1-&gt;next;
        p2 = p2-&gt;next;
    }
    return true;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    struct Node* head = createList(n);
    printf("%s\n", isPalindrome(head) ? "True" : "False");
    freeList(head);
    return 0;
}





