void multiplyMatrices(int r1, int c1, int **A, int r2, int c2, int **B, int **C) {
    for (int i = 0; i &lt; r1; i++) {
        for (int j = 0; j &lt; c2; j++) {
            C[i][j] = 0;
            for (int k = 0; k &lt; c1; k++) {
