#include &lt;stdio.h&gt;
#include &lt;string.h&gt;
#include &lt;stdlib.h&gt;

void compress(char *s) {
    int n = strlen(s);
    char *res = (char *)malloc((2 * n + 1) * sizeof(char));
    int k = 0;

    for (int i = 0; i &lt; n; i++) {
        int count = 1;
        while (i &lt; n - 1 && s[i] == s[i+1]) {
            count++;
            i++;
        }
        res[k++] = s[i];
        k += sprintf(&res[k], "%d", count);
    }
    res[k] = '\0';
    printf("%s\n", res);
    free(res);
}

int main() {
