Q8: The Array Rotator
Description: Rotate array Left or Right by K positions.






Sample Input



5
1 2 3 4 5
0
1








Sample Output



2 3 4 5 1








Solution





#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

void reverse(int arr[], int start, int end) {
    while (start &lt; end) {
        int temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++; end--;
    }
}

void rotate(int arr[], int n, int d, int k) {
    if (n == 0) return;
    k %= n;
    if (d == 0) { // Left
        reverse(arr, 0, k - 1);
        reverse(arr, k, n - 1);
        reverse(arr, 0, n - 1);
    } else { // Right
        reverse(arr, 0, n - 1);
        reverse(arr, 0, k - 1);
        reverse(arr, k, n - 1);
    }
}

int main() {
    int n, d, k;
    if (scanf("%d", &n) != 1) return 1;
    int *arr = (int *)malloc(n * sizeof(int));
    for (int i = 0; i &lt; n; i++) scanf("%d", &arr[i]);
    if (scanf("%d %d", &d, &k) != 2) { free(arr); return 1; }

    rotate(arr, n, d, k);
    for (int i = 0; i &lt; n; i++) printf("%d%s", arr[i], (i == n - 1) ? "" : " ");
    printf("\n");
    free(arr);
    return 0;
}

