#include &lt;stdlib.h&gt;

int searchRotated(int arr[], int n, int target) {
    int low = 0, high = n - 1;
    while (low &lt;= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target) return mid;
        if (arr[low] &lt;= arr[mid]) {
            if (target &gt;= arr[low] && target &lt; arr[mid]) high = mid - 1;
            else low = mid + 1;
        } else {
            if (target &gt; arr[mid] && target &lt;= arr[high]) low = mid + 1;
            else high = mid - 1;
        }
    }
    return -1;
}

