#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int canShip(int w[], int n, int cap, int d) {
    int days = 1, current = 0;
    for (int i = 0; i &lt; n; i++) {
        if (w[i] &gt; cap) return 0;
        if (current + w[i] &gt; cap) {
            days++;
            current = w[i];
        } else current += w[i];
    }
    return days &lt;= d;
}

int minCapacity(int w[], int n, int d) {
    int low = 0, high = 0;
    for (int i = 0; i &lt; n; i++) {
