        high += w[i];
    }
    int ans = high;
    while (low &lt;= high) {
        int mid = low + (high - low) / 2;
        if (canShip(w, n, mid, d)) {
            ans = mid;
            high = mid - 1;
        } else low = mid + 1;
    }
    return ans;
}

int main() {
